components-button--states.snippet:
import { Component } from '@angular/core';
import { ButtonComponent } from './button.component';

@Component({
  selector: 'app-demo',
  imports: [ButtonComponent],
  template: `
    <div
        style="display: grid; grid-template-columns: repeat(2, max-content); gap: var(--dma-spacing-16)">
        @for (variant of variants; track variant) {
        <button
            dma-button
            type="button"
            [variant]="variant">
            {{ labels[variant] }}
        </button>
        <button
            dma-button
            type="button"
            [variant]="variant"
            disabled>
            {{ labels[variant] }}
        </button>
        }
    </div>`,
})
export class DemoComponent {}
